const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',book:'M12 5v16M12 5C8 2 4 3 2 4v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-2-1-6-2-10 1Z',practice:'m14 3 7 7-11 11H3v-7L14 3ZM12 5l7 7M3 21l5-1-4-4',headphones:'M3 14v-3a9 9 0 0 1 18 0v3M3 13h4v8H5a2 2 0 0 1-2-2v-6ZM21 13h-4v8h2a2 2 0 0 0 2-2v-6Z',chart:'M4 3v18h17M8 16v-4M13 16V8M18 16V5',arrow:'M4 12h15m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',clock:'M12 8v4l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',calendar:'M8 2v4M16 2v4M3 9h18M4 4h16v17H4V4Z',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',play:'m8 5 11 7-11 7V5Z',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',download:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',repeat:'m17 2 4 4-4 4M3 11V8a2 2 0 0 1 2-2h16M7 22l-4-4 4-4m14-1v3a2 2 0 0 1-2 2H3',close:'m6 6 12 12M18 6 6 18',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0V5ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8',stop:'M6 6h12v12H6Z',external:'M14 3h7v7m0-7L10 14M11 3H3v18h18v-8',leaf:'M20 3C6 1 2 9 5 16c7 5 16 0 15-13ZM4 21 16 8'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.book}"/></svg>`;
const storageKey='entre-trazos-v1';
const fresh=()=>({version:1,records:{},sessions:[],settings:{pinyin:true,extra:false},checklist:{},flashcards:flashDefaults(),pronunciation:{attempts:0,correct:0,history:[]}});
let storageWarning=false;
function validState(raw){
  if(!raw||raw.version!==1||!raw.records||Array.isArray(raw.records)||!Array.isArray(raw.sessions))throw Error('El archivo no es una copia de progreso de Un poco de chino.');
  const out=fresh(),ids=new Set(questions.map(q=>q.id));
  for(const [id,r] of Object.entries(raw.records)){
    if(!ids.has(id))continue;
    if(!r||!['attempts','correct','errors','streak','last','due'].every(k=>Number.isFinite(r[k])&&r[k]>=0)||r.correct+r.errors!==r.attempts||r.streak>r.correct||typeof r.resolved!=='boolean')throw Error('Hay datos de progreso no válidos.');
    out.records[id]={attempts:r.attempts,correct:r.correct,errors:r.errors,streak:r.streak,last:r.last,due:r.due,resolved:r.resolved};
  }
  out.sessions=raw.sessions.filter(s=>s&&Number.isFinite(s.date)&&s.date>0&&Number.isInteger(s.correct)&&Number.isInteger(s.total)&&s.total>0&&s.total<=8&&s.correct>=0&&s.correct<=s.total).slice(-200);
  out.settings={pinyin:raw.settings?.pinyin!==false,extra:raw.settings?.extra===true};
  for(const id of ['sounds','writing','countries','reading','bu','oral'])out.checklist[id]=raw.checklist?.[id]===true;
  out.flashcards=validateFlashState(raw.flashcards);
  const sound=raw.pronunciation;
  if(sound&&Number.isInteger(sound.attempts)&&Number.isInteger(sound.correct)&&sound.correct>=0&&sound.attempts>=sound.correct){out.pronunciation={attempts:sound.attempts,correct:sound.correct,history:Array.isArray(sound.history)?sound.history.filter(h=>h&&Number.isFinite(h.date)&&typeof h.correct==='boolean'&&typeof h.syllable==='string'&&[1,2,3,4,5].includes(h.tone)&&['tone','sound','twister'].includes(h.mode)).slice(-200):[]};}
  return out;
}
let state;
try{state=localStorage.getItem(storageKey)?validState(JSON.parse(localStorage.getItem(storageKey))):fresh();}catch{state=fresh();storageWarning=true;}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));return true;}catch{storageWarning=true;toast('El navegador no ha podido guardar el progreso. Expórtalo desde Progreso.');return false;}}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5500);}
const button=(label,href,style='primary',symbol='arrow')=>`<a class="button ${style}" href="#${href}">${label}${icon(symbol)}</a>`;
const tag=text=>`<span class="tag">${text}</span>`;
let lessonTab='vocabulario',session=null,selected=null,ordered=[],search='',category='todos',audioUnit='1',activeTrack=null,tracks=[],audioURL=null,recordURL=null,recorder=null,recordStream=null,audioDB=null,importing=false,loopStart=null,loopEnd=null,loopEnabled=false;
let route='hoy',selectedLesson=2,practiceScope='',recognitionHelp=false;
const lessonVocab=()=>vocabulary.filter(v=>v.extra||sessionsForSource(v.source).includes(selectedLesson));
const studyTools=createStudyTools({getState:()=>state,save,render,toast,icon,escape});
const pronunciation=createPronunciation({getState:()=>state,save,render,toast,escape,icon});
const navItems=[['hoy','Hoy','home'],['sesiones','Sesiones','book'],['practicar','Practicar','practice'],['tarjetas','Tarjetas','repeat'],['sonidos','Sonidos','headphones'],['audios','Libro','book'],['progreso','Progreso','chart']];
function nav(){ $('#navigation').innerHTML=navItems.map(([id,label,symbol])=>`<a href="#${id}" class="${(route===id||(id==='sesiones'&&route==='sesion'))?'active':''}" ${(route===id||(id==='sesiones'&&route==='sesion'))?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span>${id==='sesiones'?'<span class="nav-badge">3</span>':''}</a>`).join(''); }
function stats(){const records=questions.filter(q=>!q.introOnly).map(q=>state.records[q.id]).filter(Boolean);return {attempts:records.reduce((n,r)=>n+r.attempts,0),correct:records.reduce((n,r)=>n+r.correct,0),pending:records.filter(r=>!r.resolved).length,seen:records.length,mastered:records.filter(r=>r.streak>=2).length,due:records.filter(r=>r.due<=Date.now()).length};}
function statsHTML(){const s=stats();return `<div class="stats"><div class="stat"><span class="stat-icon">${icon('practice')}</span><div><strong>${s.seen}<span style="font-size:13px;color:var(--muted)"> / ${questions.filter(q=>!q.introOnly&&(state.settings.extra||!q.extra)).length}</span></strong><small>ejercicios practicados</small></div></div><div class="stat"><span class="stat-icon">${icon('check')}</span><div><strong>${s.attempts?Math.round(s.correct/s.attempts*100)+'%':'—'}</strong><small>aciertos acumulados</small></div></div><div class="stat"><span class="stat-icon">${icon('repeat')}</span><div><strong>${s.pending}</strong><small>errores por repasar</small></div></div></div>`;}
function today(){
 const now=new Date(),month=now.toLocaleDateString('es',{month:'short'}).replace('.','').toUpperCase();
 return `<div class="intro"><div><span class="eyebrow">PASO A PASO, CADA DÍA</span><h1>Un poco de chino.</h1><p>Vuelve a lo aprendido. Dale forma a lo que sabes.</p></div><div class="today-stamp">${month}<strong>${now.getDate()}</strong>${now.toLocaleDateString('es',{weekday:'short'}).replace('.','').toUpperCase()}</div></div>
 <section class="hero"><div><span class="eyebrow">TU REPASO DE HOY · SESIONES 1–3</span><h2>Una presentación.<br>Muchas formas de practicar.</h2><p>Sonidos, caracteres y primeras conversaciones.<br>Ocho ejercicios, un pequeño paso adelante.</p>${button('Empezar mi repaso','practicar')}</div><div class="hero-art"><div class="hero-hanzi hanzi" lang="zh-Hans">你是谁？</div><div class="pinyin">Nǐ shì shéi?</div><span class="translation">¿Quién eres?</span><span class="hero-seal hanzi" lang="zh-Hans">学</span></div></section>
 ${statsHTML()}<div class="section-head"><h2>Tu cuaderno, abierto.</h2><span class="muted">Al ritmo de tu clase</span></div><div class="dashboard-grid"><section class="card lesson-card">${tag('TUS CLASES · SESIONES 1–3')}<h3 class="hanzi" lang="zh-Hans">你好！我叫…</h3><div class="pinyin">Nǐ hǎo! Wǒ jiào…</div><p>Saludar, presentarte y preguntar por los demás.<br>Construye una conversación con lo que ya conoces.</p><div class="lesson-meta"><span>${icon('book')}Sonidos, palabras y frases</span><span>${icon('practice')}Tres sesiones de clase</span></div><div class="card-actions"><small>Materiales de S1, S2 y S3</small><a class="text-link" href="#sesiones">Abrir sesiones ${icon('arrow')}</a></div></section>
 <section class="card weekly-card"><span class="eyebrow">${icon('calendar')} DEL AULA AL CUADERNO</span><h3>Esta semana, afina el oído.</h3><ul class="weekly-list"><li>${icon('check')}Sonidos del dossier de pinyin</li><li>${icon('check')}Países y preguntas con 吗</li><li>${icon('check')}El cambio de tono de 不</li><li>${icon('check')}Caligrafía y comprensión oral</li></ul><a class="text-link" href="#semana">Ver mi lista de práctica ${icon('arrow')}</a></section></div>
 <div class="daily-note"><span class="hanzi" lang="zh-Hans">不</span><p><strong>Un detalle para llevarte hoy.</strong> En 不是, 不 se pronuncia <em>bú</em>: cambia a segundo tono delante de shì.<small>Sesión 3 · Negación y tonos · p. 41</small></p></div>`;
}

function sessionsPage(){return `<span class="eyebrow">TU CUADERNO, CLASE A CLASE</span><h1>Mis sesiones.</h1><p class="page-description">Los materiales que has trabajado, organizados como tus clases. El libro queda como referencia dentro de cada sesión.</p><div class="class-grid">${classes.map(c=>`<article class="card class-card"><span class="tag">SESIÓN ${c.id}</span><h2>${c.title}</h2><p>${c.subtitle}</p><ul>${c.topics.map(t=>`<li>${t}</li>`).join('')}</ul><div class="source-note">${c.sources.join('<br>')}</div><a class="button primary" href="#sesion-${c.id}">Abrir sesión ${icon('arrow')}</a></article>`).join('')}</div><div class="source-callout"><p><strong>Material inicial complementario:</strong> «3. U1.pdf» contiene saludos y trazos, pero no lleva etiqueta S1. Está accesible junto a S1 como complemento, sin atribuirle una sesión confirmada.</p></div><section class="card recognition-banner"><div><span class="eyebrow">SÉ DECIRLO. QUIERO RECONOCERLO.</span><h2>Del pinyin a los caracteres.</h2><p>Reconoce 认识 a partir de rènshi, o construye en caracteres una frase que ya conoces.</p></div><button class="button primary" data-train="recognition" data-scope="">Entrenar reconocimiento ${icon('arrow')}</button></section>`;}
function unit(){const c=classes.find(c=>c.id===selectedLesson);const tabs=selectedLesson===1?[['fundamentos','Sonidos'],['vocabulario','Vocabulario'],['caracteres','Caracteres'],['saludos','Complemento U1'],['libro','Apoyo del libro']]:[['vocabulario','Vocabulario'],['gramatica','Estructuras'],['conversacion','Conversación'],['libro','Apoyo del libro']];if(!tabs.some(([id])=>id===lessonTab))lessonTab=tabs[0][0];return `<a class="text-link" href="#sesiones">← Todas las sesiones</a><span class="eyebrow spaced">SESIÓN ${c.id} · ${c.book}</span><h1>${c.title}</h1><p class="page-description">${c.subtitle}</p><p class="source-note">Fuentes: ${c.sources.join(' · ')}</p><div class="button-row"><button class="button primary" data-train="daily" data-scope="${c.id}">Repasar esta sesión ${icon('arrow')}</button><button class="button secondary" data-train="${c.id===1?'foundation':'recognition'}" data-scope="${c.id}">${c.id===1?'Escuchar y practicar':'Reconocer caracteres'} ${icon('practice')}</button><button class="button ghost" data-card-start="s${c.id}">Tarjetas de esta sesión ${icon('repeat')}</button></div><div class="controls"><div class="tabs" role="tablist" aria-label="Contenido de la sesión">${tabs.map(([id,text])=>`<button role="tab" aria-selected="${lessonTab===id}" data-tab="${id}" class="${lessonTab===id?'selected':''}">${text}</button>`).join('')}</div><label class="switch-label"><input type="checkbox" id="show-pinyin" ${state.settings.pinyin?'checked':''}>Mostrar pinyin</label>${selectedLesson!==1&&lessonTab!=='libro'?`<label class="switch-label"><input type="checkbox" id="extra-vocab" ${state.settings.extra?'checked':''}>Un poco más</label>`:''}</div><div id="lesson-content">${lessonTab==='libro'?bookSupportHTML(selectedLesson,state.settings.pinyin):selectedLesson===1?foundationHTML():lessonContent()}</div>`;}
function foundationHTML(){
 if(lessonTab==='vocabulario')return `<div class="note-box">Palabras y términos que aparecen en la introducción de S1. Los caracteres utilizados como ejemplos de escritura y tonos tienen un mazo opcional separado.</div>${vocabCards()}<button class="button secondary spaced" data-card-start="s1-examples">Ejemplos de caracteres de S1 ${icon('repeat')}</button>`;
 if(lessonTab==='saludos')return `<div class="note-box">Complemento procedente de «3. U1.pdf», sin número de sesión en su nombre. Saludos, despedidas y cortesía.</div><div class="vocab-grid">${[['你好','nǐ hǎo','hola'],['你们好','nǐmen hǎo','hola, a un grupo'],['您好','nín hǎo','hola, de cortesía'],['再见','zàijiàn','adiós'],['拜拜','báibái','chao / adiós informal']].map(([h,p,m])=>`<article class="card vocab-card"><div class="hanzi" lang="zh-Hans">${h}</div>${state.settings.pinyin?`<div class="pinyin">${p}</div>`:''}<div class="meaning">${m}</div><span class="source">U1 · saludos y despedidas</span></article>`).join('')}</div>`;
 if(lessonTab==='caracteres')return `<div class="grammar-list">${characterNotes.map(([h,b])=>`<article class="card"><h2>${h}</h2><p>${b}</p></article>`).join('')}</div><p class="source-note spaced">Resumen de estudio: S1 · El idioma chino, pp. 25–27 y 37–65. Los ejemplos de palabras de S2 se usan como puente con tu práctica actual.</p><section class="card spaced"><h2>Ejemplos del PDF de S1</h2><p>日, 月, 木, 林, 休 y los contrastes de tonos 汤、糖、躺、烫 aparecen para explicar cómo funcionan los caracteres. Puedes repasarlos en un mazo opcional.</p><button class="button secondary" data-card-start="s1-examples">Practicar ejemplos de S1 ${icon('repeat')}</button></section>`;
 const groups=(heading,list)=>`<section class="card"><h2>${heading}</h2><div class="sound-groups">${list.map(([sounds,note])=>`<div><strong>${sounds}</strong><small>${note}</small></div>`).join('')}</div></section>`;
 return `<div class="note-box"><strong>Una sílaba, tres piezas:</strong> inicial + final + tono. En mā: m + a + primer tono. Hay sílabas sin consonante inicial. Aquí tienes una ficha de referencia. En Sonidos puedes escuchar las sílabas y practicar con grabaciones.</div><div class="sound-grid">${groups('Iniciales · consonantes',initialGroups)}${groups('Finales · vocales y combinaciones',finalGroups)}</div><section class="card spaced"><h2>Cuatro tonos y tono neutro</h2><div class="tone-grid">${tones.map(([syllable,note,description])=>`<div><strong>${syllable}</strong><span>Tono ${note}</span><small>${description}</small></div>`).join('')}</div><p class="source-note spaced">El tercer tono cambia en el habla encadenada. Por ejemplo, 你好 suele escribirse nǐ hǎo, aunque la primera sílaba se pronuncia con segundo tono. El tono neutro aparece como complemento de estudio.</p></section><div class="source-callout"><p>y y w se utilizan en la escritura del pinyin para ciertas sílabas sin consonante inicial. ü no equivale a u. En las combinaciones con j, q y x, ü se escribe sin diéresis. Las abreviaturas iu, ui y un dependen del contexto ortográfico.</p></div><p class="source-note spaced">S1 · pinyin, pp. 2–9; El idioma chino, pp. 67–78. Ficha adaptada para repasar, con notas explicativas.</p><div class="button-row"><a class="button primary" href="#sonidos">Escuchar sílabas y tonos</a><a class="button ghost" href="https://yoyochinese.com/chinese-learning-tools/Mandarin-Chinese-pronunciation-lesson/pinyin-chart-table" target="_blank" rel="noopener noreferrer">Escuchar en la tabla de pinyin ${icon('external')}</a><button class="button primary" data-train="foundation" data-scope="1">Escuchar y practicar ${icon('arrow')}</button></div>`;
}

function vocabCards(){const list=lessonVocab().filter(v=>(state.settings.extra||!v.extra)&&(category==='todos'||v.category===category)&&`${v.hanzi} ${v.pinyin} ${v.meaning}`.normalize('NFD').replace(/\p{M}/gu,'').toLowerCase().includes(search.normalize('NFD').replace(/\p{M}/gu,'').toLowerCase()));return `<p class="count-label">${list.length} palabras y expresiones${state.settings.extra?' · ampliación activada':' · solo lo visto en clase'}</p><div class="vocab-grid">${list.map(v=>`<article class="card vocab-card"><span class="category">${v.category}</span>${v.extra?'<span class="extra-tag">EXTRA</span>':''}<div class="hanzi" lang="zh-Hans">${v.hanzi}</div>${state.settings.pinyin?`<div class="pinyin">${v.pinyin}</div>`:''}<div class="meaning">${v.meaning}</div><div class="source">${v.source}</div></article>`).join('')||'<p class="empty-state">No hay palabras con ese filtro. Prueba otra búsqueda.</p>'}</div>`;}
function lessonContent(){
 if(lessonTab==='vocabulario')return `<div class="controls"><input class="search" id="vocab-search" type="search" placeholder="Busca en chino, pinyin o español" aria-label="Buscar vocabulario" value="${escape(search)}"><select class="filter-select" id="category" aria-label="Filtrar por tema">${[['todos','Todos los temas'],['personas','Personas'],['estructuras','Estructuras'],['países','Países'],['expresiones','Expresiones']].map(([id,text])=>`<option value="${id}" ${category===id?'selected':''}>${text}</option>`).join('')}</select></div><div id="vocab-results">${vocabCards()}</div>`;
 if(lessonTab==='gramatica')return `<div class="grammar-list">${grammar.filter(g=>selectedLesson===2?['names','how-are-you'].includes(g.id):!['names','how-are-you'].includes(g.id)).map((g,i)=>`<details class="card grammar" ${i===0?'open':''}><summary><span class="hanzi" lang="zh-Hans">${g.tag}</span>${g.title}</summary><div class="grammar-body"><p>${g.body}</p><div class="pattern">${g.pattern}</div>${g.examples.map(([h,p,m])=>`<div class="example"><div class="hanzi" lang="zh-Hans">${h}</div>${state.settings.pinyin?`<div class="pinyin">${p}</div>`:''}<div class="meaning">${m}</div></div>`).join('')}<div class="grammar-note">${g.note}</div><div class="source-note">${g.source}</div></div></details>`).join('')}</div>`;
 return `<section class="card"><span class="eyebrow">PRÁCTICA CREADA · SESIÓN ${selectedLesson}</span><h2>Una conversación para reconocer.</h2>${dialogues[selectedLesson].map(([who,h,p,m])=>`<div class="example"><span class="tag">${who}</span><div class="hanzi" lang="zh-Hans">${h}</div>${state.settings.pinyin?`<div class="pinyin">${p}</div>`:''}<div class="meaning">${m}</div></div>`).join('')}<div class="note-box">Primero reconoce la frase completa. Después busca sus piezas. Por ejemplo: 认识 → rènshi, 你 → nǐ, 很 → hěn, 高兴 → gāoxìng.</div><button class="button primary" data-train="recognition" data-scope="${selectedLesson}">Entrenar reconocimiento ${icon('arrow')}</button></section>`;
}
function practice(){if(session)return session.finished?resultHTML():questionHTML();const s=stats();return `<span class="eyebrow">ELIGE QUÉ QUIERES REFORZAR</span><h1>Practicar a tu ritmo.</h1><p class="page-description">Puedes repasar tu clase o concentrarte en reconocer por escrito lo que ya sabes decir.</p><div class="controls"><label for="practice-scope">Contenido</label><select class="filter-select" id="practice-scope"><option value="">Todas las sesiones</option>${classes.map(c=>`<option value="${c.id}" ${practiceScope===String(c.id)?'selected':''}>Sesión ${c.id}</option>`).join('')}</select><label class="switch-label"><input id="practice-extra" type="checkbox" ${state.settings.extra?'checked':''}>Añadir vocabulario extra al repaso</label></div><div class="practice-start"><section class="card"><span class="eyebrow">SÉ DECIRLO. QUIERO RECONOCERLO.</span><span class="hanzi decor" lang="zh-Hans">认识</span><h2>Del pinyin a los caracteres.</h2><p>Ves <strong>Rènshi nǐ hěn gāoxìng</strong> y buscas sus caracteres. Empieza por palabras y continúa con frases. La ayuda bajo las opciones se revela solo si la necesitas.</p><div class="button-row"><button class="button primary" id="start-recognition">Reconocer palabras ${icon('arrow')}</button><button class="button secondary" id="start-phrases">Frases conocidas ${icon('practice')}</button></div><p class="source-note spaced">Hasta 8 retos · sin teclado chino · progreso propio por ejercicio</p></section><section class="card"><span class="eyebrow">MI REPASO DE CLASE</span><h2>Mezclar lo aprendido.</h2><p>Significado, pinyin, estructuras y reconocimiento, con el contenido de la sesión elegida. Los errores que toca revisar tienen prioridad.</p><div class="button-row"><button class="button primary" id="start-session">Empezar repaso ${icon('arrow')}</button><button class="button secondary" id="start-errors" ${s.pending?'':'disabled'}>Repasar errores ${icon('repeat')}</button></div><p class="source-note spaced">Hasta 8 ejercicios · sin límite de tiempo</p><div class="record-section"><h3>Iniciales, finales y tonos</h3><p>Escucha sílabas, compara sus tonos y reconoce lo que oyes, con los sonidos de S1.</p><button class="button ghost" data-train="foundation" data-scope="1">Escuchar y practicar ${icon('arrow')}</button></div></section></div>`;}

// Reading aids are withheld in pinyin and tone questions so they do not reveal the answer.
const readingKey=text=>text.replace(/[\s。！？?!，,.、]/g,'');
const readings=new Map(vocabulary.map(v=>[readingKey(v.hanzi),v.pinyin]));
for(const g of grammar)for(const [h,p] of g.examples)readings.set(readingKey(h),p);
for(const [h,p] of [['中国人','Zhōngguórén'],['西班牙人','Xībānyárén'],['安娜','Ānnà'],['我姓王','Wǒ xìng Wáng'],['你姓什么','Nǐ xìng shénme'],['我叫安娜','Wǒ jiào Ānnà'],['他是中国人','Tā shì Zhōngguórén'],['你是中国人吗','Nǐ shì Zhōngguórén ma'],['不是','bú shì'],['认识你很高兴','Rènshi nǐ hěn gāoxìng'],['很','hěn'],['我是中国人','Wǒ shì Zhōngguórén']])readings.set(readingKey(h),p);
function readingAid(text,override){if(session&&!session.finished&&session.items[session.index]?.kind==='recognition'&&!recognitionHelp)return '';const reading=override||readings.get(readingKey(text));return (session&&!session.finished&&session.items[session.index]?.kind==='recognition'?recognitionHelp:state.settings.pinyin)&&reading?`<span class="reading-aid" lang="zh-Latn-pinyin">${reading}</span>`:'';}
function blockHTML(text){return `<span lang="zh-Hans">${text}</span>${readingAid(text,text==='不'?'bú':undefined)}`;}
function questionHTML(){
 const q=session.items[session.index],done=!!session.feedback,showAid=q.type!=='pinyin'&&q.skill!=='Tonos'&&q.kind!=='foundation';
 let response;
 if(q.type==='choice')response=`<div class="options">${q.options.map((v,i)=>`<button class="option ${selected===v?'chosen':''} ${done&&v===q.answer?'correct':''} ${done&&selected===v&&!session.feedback.correct?'wrong':''}" data-option="${i}" ${done?'disabled':''}><span class="option-index">${String.fromCharCode(65+i)}</span><span>${v}${showAid?readingAid(v):''}</span></button>`).join('')}</div>`;
 else if(q.type==='order')response=`<div class="answer-zone" aria-label="Tu frase">${ordered.map(i=>`<button class="token in-answer" data-remove="${i}" aria-label="Quitar ${q.tokens[i]}" ${done?'disabled':''}>${blockHTML(q.tokens[i])}</button>`).join('')}</div><div class="token-bank" aria-label="Bloques disponibles">${q.tokens.map((v,i)=>`<button class="token ${ordered.includes(i)?'used':''}" data-token="${i}" aria-label="Añadir ${v}" ${done||ordered.includes(i)?'disabled':''}>${blockHTML(v)}</button>`).join('')}</div><p class="input-help">Toca los bloques para construir la frase, sin teclado chino. Para corregirla, toca una palabra de tu frase y vuelve a colocarla.</p>`;
 else response=`<label class="field-label" for="answer">Tu respuesta en pinyin</label><input class="answer-input" id="answer" autocomplete="off" autocapitalize="off" spellcheck="false" ${done?'disabled':''} value="${escape(selected||'')}" placeholder="Por ejemplo: ni3 o nǐ"><p class="input-help">Usa tu teclado habitual: acepta marcas de tono o números del 1 al 4. Para tono neutro, escribe sin número, con 5 o con 0.</p><div class="tone-keys" aria-label="Vocales con tono">${[...'āáǎàēéěèīíǐìōóǒòūúǔùǖǘǚǜ'].map(c=>`<button data-insert="${c}" ${done?'disabled':''}>${c}</button>`).join('')}</div>`;
 const ready=q.type==='order'?ordered.length===q.tokens.length:!!selected?.trim();
 return `<div class="session-shell"><div class="session-header"><span>${session.scope?'SESIÓN '+session.scope:'SESIONES 1–3'} · ${session.mode==='errors'?'MIS ERRORES':session.mode.startsWith('recognition')?'RECONOCER CARACTERES':session.mode==='foundation'?'LAS BASES':'MI REPASO'}</span><button class="text-link" id="exit-session">Salir ${icon('close')}</button></div><div class="progress-bar" role="progressbar" aria-label="Avance del repaso" aria-valuenow="${session.index}" aria-valuemin="0" aria-valuemax="${session.items.length}"><span style="width:${session.index/session.items.length*100}%"></span></div><section class="card question-card"><div class="question-meta">${tag(q.skill.toUpperCase())}<span class="muted" style="font-size:11px">${session.index+1} de ${session.items.length}</span>${q.extra?tag('EXTRA'):''}</div>${showAid?`<label class="switch-label question-aid"><input type="checkbox" id="practice-pinyin" ${(q.kind==='recognition'?recognitionHelp:state.settings.pinyin)?'checked':''}>${q.kind==='recognition'?'Revelar pinyin de las opciones':'Mostrar pinyin'}</label>`:''}<h2>${q.prompt}</h2>${q.cue?`<div class="recognition-cue" lang="zh-Latn-pinyin">${q.cue}${q.cueMeaning?`<small>${q.cueMeaning}</small>`:''}</div>`:''}${q.hanzi?`<div class="question-hanzi hanzi" lang="zh-Hans">${q.hanzi}${showAid?readingAid(q.hanzi):''}</div>`:''}${response}
 ${done?`<div class="feedback ${session.feedback.correct?'':'incorrect'}" role="status"><strong>${icon(session.feedback.correct?'check':'leaf')}${session.feedback.correct?'Bien recordado.':'Una oportunidad para afianzarlo.'}</strong>${session.feedback.correct?'':`<div class="correct-answer">${q.answer}${q.type==='order'?'。':''}</div>`}<p>${q.explanation}</p></div>`:''}<div class="question-bottom"><span class="source-note">Práctica creada · ${q.source}</span>${done?`<button class="button primary" id="next-question">${session.index===session.items.length-1?'Ver mi resumen':'Siguiente'} ${icon('arrow')}</button>`:`<button class="button primary" id="check-answer" ${ready?'':'disabled'}>Comprobar ${icon('check')}</button>`}</div></section></div>`;
}
function resultHTML(){const correct=session.answers.filter(a=>a.correct).length;return `<div class="session-shell"><section class="card session-result"><span class="eyebrow">UN PASO MÁS</span><span class="result-mark hanzi" lang="zh-Hans">好</span><h1>Un ratito bien invertido.</h1><div class="result-score">${correct}<span style="font-size:25px;color:var(--muted)"> / ${session.items.length}</span></div><p>respuestas correctas en este repaso</p><div class="result-list">${session.answers.map(a=>`<div class="result-row ${a.correct?'':'failed'}">${icon(a.correct?'check':'repeat')}<span>${a.question.skill}${a.question.hanzi?` · <span class="hanzi" lang="zh-Hans">${a.question.hanzi}</span>`:''}</span><small>${a.correct?'Recordado':'Para volver a practicar'}</small></div>`).join('')}</div><p>Tu progreso está ${storageWarning?'en memoria; expórtalo para conservarlo':'guardado en este navegador'}. Los errores quedan en tu lista de repaso.</p><div class="button-row"><button class="button primary" id="new-session">Otro pequeño repaso ${icon('repeat')}</button>${button('Ver mi progreso','progreso','ghost','chart')}</div></section></div>`;}
function startSession(mode='daily'){if(mode==='foundation'||(practiceScope==='1'&&mode!=='errors')){session=null;location.hash='sonidos';return;}const items=makeSession(state.records,state.settings.extra,mode,Math.random,Date.now(),{session:practiceScope});if(!items.length){toast('No hay ejercicios pendientes para esa selección. Prueba con todas las sesiones.');return;}recognitionHelp=false;session={items,index:0,answers:[],feedback:null,finished:false,mode,scope:practiceScope};selected=null;ordered=[];render();}
function checkAnswer(){const q=session.items[session.index];const value=q.type==='order'?ordered.map(i=>q.tokens[i]).join(''):selected;if(!value||(q.type==='order'&&ordered.length!==q.tokens.length))return;const correct=isCorrect(q,value);state.records[q.id]=updateRecord(state.records[q.id],correct);session.answers.push({question:q,correct});session.feedback={correct};save();render();$('#next-question')?.focus();}
function nextQuestion(){if(session.index===session.items.length-1){session.finished=true;state.sessions.push({date:Date.now(),correct:session.answers.filter(a=>a.correct).length,total:session.items.length});state.sessions=state.sessions.slice(-200);save();}else{session.index++;recognitionHelp=false;session.feedback=null;selected=null;ordered=[];}render();}

const weekTasks=[['sounds','Pinyin y oído','Practicar los grupos del dossier indicados por la profesora. El último mensaje menciona «JGH» (4.1 y 4.2); confirma ese rótulo con el dossier. Repasar también BP (2.1–2.2) y DT (3.1–3.2).'],['writing','Caligrafía','Completar la práctica de los caracteres nuevos de la p. 34, en papel.'],['countries','Países','Practicar la ficha de caligrafía de los países y sus nombres.'],['reading','Lectura y estructuras','Repasar pp. 26–28 y la parte trabajada de p. 29, junto con S3.'],['bu','El tono de 不','Hacer la práctica de la p. 28 y comprobar en qué casos se pronuncia bú.'],['oral','Comprensión oral','Libro: ejercicio 2 de p. 18. Ficha: «U2 CO» y completar el diálogo. Estos audios y la ficha aún no están identificados en la app.']];
function weekHTML(){return `<span class="eyebrow">DEL AULA AL CUADERNO</span><h1>Esta semana.</h1><p class="page-description">Una lista personal a partir de los mensajes de la profesora. Márcala a tu ritmo.</p><div class="note-box">El texto recibido contiene rótulos de fecha que no coinciden entre sí. Esta lista sigue el contenido del último bloque de deberes, sin asignarle una fecha límite automática.</div><section class="card checklist">${weekTasks.map(([id,title,body])=>`<label class="${state.checklist[id]?'done':''}"><input type="checkbox" data-task="${id}" ${state.checklist[id]?'checked':''}><span><strong>${title}</strong><br>${body}</span></label>`).join('')}</section><div class="source-callout"><p>Audición ya identificada por el foro: <strong>pista 01-3 → libro, p. 6, ejercicio 2</strong>. Las pistas del dossier y «U2 CO» no aparecen con esos nombres en el ZIP del libro.</p></div><div class="resources"><a class="resource" href="https://yoyochinese.com/chinese-learning-tools/Mandarin-Chinese-pronunciation-lesson/pinyin-chart-table" target="_blank" rel="noopener noreferrer"><span>Tabla interactiva de pinyin<small>Recurso enlazado por la profesora · Yoyo Chinese</small></span>${icon('external')}</a><a class="resource" href="https://www.youtube.com/@GraceMandarinChinese/search?query=Pronunciation%20Training" target="_blank" rel="noopener noreferrer"><span>Práctica de pronunciación<small>Recurso enlazado por la profesora · Grace Mandarin Chinese</small></span>${icon('external')}</a><a class="resource" href="https://wordwall.net/play/63429/529/893?wwmethod=link" target="_blank" rel="noopener noreferrer"><span>Países y preguntas con 吗<small>Actividad enlazada por la profesora · Wordwall</small></span>${icon('external')}</a></div>`;}

function progressHTML(){const s=stats(),skills=[...new Set(questions.filter(q=>!q.extra&&!q.introOnly).map(q=>q.skill))],errors=questions.filter(q=>!q.introOnly&&state.records[q.id]&&!state.records[q.id].resolved);return `<span class="eyebrow">LO QUE VAS CONSTRUYENDO</span><h1>Cada intento cuenta.</h1><p class="page-description">Una vista de tu práctica, para saber dónde volver a poner la atención.</p>${statsHTML()}<section class="card spaced"><h2>Tu oído también aprende.</h2><p>${state.pronunciation.attempts?`${state.pronunciation.correct} aciertos de ${state.pronunciation.attempts} intentos en tonos, sílabas y trabalenguas.`:"Aún no has hecho ejercicios de escucha."}</p><a class="button secondary" href="#sonidos">Practicar sonidos</a></section><div class="progress-grid spaced"><section class="card"><h2>Así va tu práctica</h2>${skills.map(skill=>{const recs=questions.filter(q=>q.skill===skill).map(q=>state.records[q.id]).filter(Boolean),attempts=recs.reduce((n,r)=>n+r.attempts,0),correct=recs.reduce((n,r)=>n+r.correct,0),pct=attempts?Math.round(correct/attempts*100):0;return `<div class="skill-row"><span>${skill}</span><span class="muted">${attempts?pct+' % · '+attempts+' intentos':'Sin practicar'}</span></div><div class="skill-meter"><span style="width:${pct}%"></span></div>`;}).join('')}<p class="source-note">Los porcentajes reflejan los aciertos acumulados, no una nota de nivel. ${s.mastered} ejercicios tienen al menos dos aciertos seguidos.</p></section><section class="card"><h2>Volver sobre mis errores</h2>${errors.length?errors.map(q=>`<div class="error-row"><div>${q.hanzi?`<span class="hanzi" lang="zh-Hans">${q.hanzi}</span>`:q.prompt}<small>${q.skill} · ${q.source}</small></div><span>Pendiente</span></div>`).join(''):'<div class="empty-state">'+icon('leaf')+'<br>Tu lista está en blanco.<br>Los errores que aparezcan te esperarán aquí.</div>'}<div class="button-row"><button class="button secondary" id="progress-errors" ${errors.length?'':'disabled'}>Repasar errores ${icon('repeat')}</button></div></section></div><section class="card storage-card"><div><h3>Tu cuaderno viaja contigo.</h3><p>Exporta el progreso para guardarlo o llevarlo a otro dispositivo.<br>Importar sustituye el progreso actual; los audios se conservan aparte.</p></div><div class="button-row"><button class="button ghost" id="export-progress">Exportar ${icon('download')}</button><button class="button ghost" id="import-progress">Importar ${icon('upload')}</button><input id="progress-file" class="hidden-input" type="file" accept="application/json,.json" aria-label="Archivo de progreso"></div></section><section class="card spaced"><h3>Qué hay en esta muestra</h3><ul class="source-list"><li>Contenido de estudio: S1 (sonidos y escritura), S2 (presentaciones), S3 (países y preguntas), y complemento U1 sin sesión confirmada.</li><li>Orientación de práctica: mensajes de la profesora facilitados por ti.</li><li>${vocabulary.filter(v=>!v.extra).length} palabras y expresiones de clase + 3 de ampliación opcional; reconocimiento de palabras y frases.</li><li>${questions.filter(q=>!q.extra&&!q.introOnly).length} ejercicios de clase + 2 de ampliación, creados para esta app.</li><li>Audios: importación personal de las 69 pistas del libro, sin publicarlas.</li></ul><p class="source-note">El progreso pertenece a este navegador. No hay cuenta, sincronización automática ni clasificación entre compañeros.</p></section>`;}

function openDB(){if(audioDB)return Promise.resolve(audioDB);return new Promise((resolve,reject)=>{const req=indexedDB.open('entre-trazos-audio',1);req.onupgradeneeded=()=>req.result.createObjectStore('tracks',{keyPath:'id'});req.onsuccess=()=>{audioDB=req.result;resolve(audioDB);};req.onerror=()=>reject(req.error);});}
async function readTracks(){try{const db=await openDB();tracks=await new Promise((resolve,reject)=>{const req=db.transaction('tracks').objectStore('tracks').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});tracks.sort((a,b)=>a.unit-b.unit||a.number-b.number);if(route==='audios')render();}catch{toast('No se pudo abrir el almacenamiento de audios en este navegador.');}}
function trackInfo(filename){const name=filename.split(/[\\/]/).pop();const m=name.match(/^(\d{1,2})[-.](\d{1,2})\.mp3$/i);if(!m||+m[1]<1||+m[1]>10||+m[2]<1||+m[2]>99)return null;return {id:`${String(+m[1]).padStart(2,'0')}-${+m[2]}`,unit:+m[1],number:+m[2],name};}
async function unzipMP3(file){
 if(file.size>120*1024*1024)throw Error('El ZIP es demasiado grande. Selecciona uno de menos de 120 MB.');
 const buffer=await file.arrayBuffer(),view=new DataView(buffer);let eocd=-1;
 for(let i=buffer.byteLength-22;i>=Math.max(0,buffer.byteLength-65557);i--){if(view.getUint32(i,true)===0x06054b50){eocd=i;break;}}
 if(eocd<0)throw Error('No se reconoce este ZIP. Puedes importar los MP3 directamente.');
 const count=view.getUint16(eocd+10,true),start=view.getUint32(eocd+16,true),result=[];let cursor=start,total=0;
 if(count>500)throw Error('El ZIP contiene demasiados archivos. Importa solo los audios del libro.');
 for(let n=0;n<count;n++){
   if(cursor+46>buffer.byteLength||view.getUint32(cursor,true)!==0x02014b50)throw Error('El ZIP está incompleto.');
   const flags=view.getUint16(cursor+8,true),method=view.getUint16(cursor+10,true),compressed=view.getUint32(cursor+20,true),size=view.getUint32(cursor+24,true),nameLen=view.getUint16(cursor+28,true),extraLen=view.getUint16(cursor+30,true),commentLen=view.getUint16(cursor+32,true),offset=view.getUint32(cursor+42,true);
   const name=new TextDecoder().decode(new Uint8Array(buffer,cursor+46,nameLen));cursor+=46+nameLen+extraLen+commentLen;
   const info=trackInfo(name);if(!info)continue;
   total+=size;if(size>20*1024*1024||total>150*1024*1024)throw Error('Los audios superan el tamaño permitido. Importa menos pistas a la vez.');
   if(flags&1)throw Error('Este ZIP está protegido por contraseña. Extrae e importa los MP3.');
   if(offset+30>buffer.byteLength||view.getUint32(offset,true)!==0x04034b50)throw Error('Una pista está incompleta.');
   const begin=offset+30+view.getUint16(offset+26,true)+view.getUint16(offset+28,true);
   if(begin+compressed>buffer.byteLength)throw Error('Una pista está incompleta.');
   let blob=new Blob([new Uint8Array(buffer,begin,compressed)],{type:'audio/mpeg'});
   if(method===8){try{blob=new Blob([await new Response(blob.stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer()],{type:'audio/mpeg'});}catch{throw Error('No se pudo descomprimir el ZIP. Extráelo e importa los MP3 directamente.');}}
   else if(method!==0)throw Error('Este formato ZIP no está soportado. Extrae e importa los MP3.');
   if(blob.size!==size)throw Error('Una pista tiene un tamaño incorrecto.');
   result.push({...info,blob});
 }
 return result;
}
async function importAudio(files){if(importing||!files.length)return;importing=true;render();try{let incoming=[];for(const file of files){if(/\.zip$/i.test(file.name))incoming.push(...await unzipMP3(file));else{const info=trackInfo(file.name);if(info){if(file.size>20*1024*1024)throw Error('Una pista supera 20 MB.');incoming.push({...info,blob:file});}}}if(!incoming.length)throw Error('No se encontraron pistas como 01-3.mp3. Selecciona el ZIP del libro o sus MP3.');const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction('tracks','readwrite');for(const t of incoming)tx.objectStore('tracks').put(t);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});await readTracks();toast(`${incoming.length} pistas guardadas en este navegador.`);}catch(e){toast(e.name==='QuotaExceededError'?'No hay espacio suficiente. Importa menos MP3 a la vez.':e.message||'No se pudieron importar los audios.');}finally{importing=false;render();}}
function audioHTML(){const list=tracks.filter(t=>String(t.unit)===audioUnit),current=tracks.find(t=>t.id===activeTrack),known=current?.id==='01-3';return `<span class="eyebrow">ESCUCHAR · REPETIR · COMPARAR</span><h1>Primero, el oído.</h1><p class="page-description">Practica con las grabaciones del libro. Un sonido cada vez, con toda tu atención.</p><section class="audio-import">${icon('upload')}<div><h3>${importing?'Importando tus audios…':'Tu libro, con voz.'}</h3><p>${tracks.length?tracks.length+' pistas disponibles en este navegador.':'Importa el ZIP del libro o selecciona varios MP3.'}<br>Los archivos se guardan en tu dispositivo.</p></div><button class="button primary" id="import-audio" ${importing?'disabled':''}>${importing?'Un momento…':tracks.length?'Añadir audios':'Cargar mis audios'} ${icon('upload')}</button><input class="hidden-input" id="audio-files" type="file" accept=".zip,.mp3,audio/mpeg" multiple aria-label="ZIP o pistas MP3 del libro"></section><div class="audio-layout"><section class="card track-panel"><div class="track-heading"><h3>Audios del libro</h3><select class="filter-select" id="audio-unit" aria-label="Filtrar por lección">${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${audioUnit===String(i+1)?'selected':''}>Lección ${i+1}${i>1?' · por explorar':''}</option>`).join('')}</select></div><div class="track-list">${list.length?list.map(t=>`<button class="track-button ${t.id===activeTrack?'selected':''}" data-track="${t.id}"><span class="track-circle">${icon('play')}</span><span>Pista ${t.id}<small>${t.id==='01-3'?'p. 6 · ejercicio 2 · referencia del foro':'Libro · contenido aún sin etiquetar'}</small></span>${t.id===activeTrack?icon('headphones'):''}</button>`).join(''):`<div class="empty-state">${icon('headphones')}<br>${tracks.length?'No has importado pistas de esta lección.':'Tus pistas aparecerán aquí.'}<br>Formatos de nombre: 01-3.mp3, 02-1.mp3…</div>`}</div></section><section class="card audio-player"><span class="eyebrow">TU RINCÓN DE ESCUCHA</span><span class="hanzi" lang="zh-Hans">听一听</span><h2>${current?'Pista '+current.id:'Escucha. Repite. Vuelve.'}</h2><p class="muted" style="font-size:12px">${known?'Libro, p. 6, ejercicio 2. Correspondencia indicada por la profesora.':current?'Escucha con el libro abierto. Esta pista aún no tiene transcripción ni ejercicio vinculado.':'Carga tus audios y elige una pista para practicar.'}</p>${current?'<audio id="book-audio" controls preload="metadata" aria-label="Audio del libro"></audio><div class="loop-controls"><button class="button ghost" id="mark-a">Marcar A</button><button class="button ghost" id="mark-b">Marcar B</button><button class="button ghost" id="toggle-loop" disabled>Repetir A–B</button><button class="button ghost" id="clear-loop">Limpiar</button></div><p class="audio-status" id="loop-status" role="status">Marca el inicio (A) y el final (B) de un fragmento.</p>':''}<div class="record-section"><h3>Ahora, tu voz.</h3><p>Graba una repetición y compárala con el modelo. La grabación es temporal y puedes descargarla. No se puntúa automáticamente.</p><button class="button secondary" id="record-voice">${icon('mic')}Grabar mi voz</button><div id="recording-result">${recordURL?'<audio controls id="voice-playback" aria-label="Tu grabación"></audio><a class="text-link" id="download-voice">Descargar mi grabación</a>':''}</div><p class="audio-status" id="record-status" role="status"></p></div></section></div><div class="source-callout"><p>La app no envía tus audios ni tus grabaciones a un servidor. La pista 01-3 está identificada por el foro; el resto se muestra por número. Los audios específicos del dossier y «U2 CO» necesitan identificarse por separado.</p></div>`;}
function wireAudio(){const track=tracks.find(t=>t.id===activeTrack);if(track){if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(track.blob);const audio=$('#book-audio');audio.src=audioURL;audio.addEventListener('timeupdate',()=>{if(loopEnabled&&loopEnd!==null&&audio.currentTime>=loopEnd)audio.currentTime=loopStart;});audio.addEventListener('ended',()=>{if(loopEnabled){audio.currentTime=loopStart;audio.play().catch(()=>{});}});audio.addEventListener('error',()=>toast('No se ha podido reproducir esta pista. Prueba a importarla de nuevo.'));}
 if(recordURL&&$('#voice-playback')){$('#voice-playback').src=recordURL;$('#download-voice').href=recordURL;$('#download-voice').download=recorder?.mimeType.includes('mp4')?'mi-practica.m4a':'mi-practica.webm';}
}
function loopStatus(){const fmt=n=>n===null?'—':n.toFixed(1)+' s';$('#loop-status').textContent=`A: ${fmt(loopStart)} · B: ${fmt(loopEnd)}${loopEnabled?' · repetición activada':''}`;$('#toggle-loop').disabled=loopStart===null||loopEnd===null;$('#toggle-loop').classList.toggle('selected',loopEnabled);$('#toggle-loop').textContent=loopEnabled?'Detener repetición':'Repetir A–B';}
async function toggleRecord(){
 if(recorder?.state==='recording'){recorder.stop();return;}
 try{
   if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('La grabación necesita un navegador compatible y HTTPS o localhost.');
   const stream=await navigator.mediaDevices.getUserMedia({audio:true});
   if(!['audios','sonidos'].includes(route)){stream.getTracks().forEach(t=>t.stop());return;}
   recordStream=stream;
   const preferred=['audio/webm;codecs=opus','audio/mp4'].find(type=>MediaRecorder.isTypeSupported(type));
   recorder=new MediaRecorder(stream,preferred?{mimeType:preferred}:undefined);const chunks=[];
   recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};
   recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());recordStream=null;if(recordURL)URL.revokeObjectURL(recordURL);recordURL=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));if(['audios','sonidos'].includes(route)&&$('#record-voice')){$('#record-voice').innerHTML=icon('mic')+'Grabar de nuevo';$('#record-status').textContent='Grabación lista. Escúchala y compárala con el modelo.';$('#recording-result').innerHTML='<audio controls id="voice-playback" aria-label="Tu grabación"></audio><a class="text-link" id="download-voice">Descargar mi grabación</a>';$('#voice-playback').src=recordURL;$('#download-voice').href=recordURL;$('#download-voice').download=recorder.mimeType.includes('mp4')?'mi-practica.m4a':'mi-practica.webm';}};
   recorder.start();$('#record-voice').innerHTML=icon('stop')+'Terminar grabación';$('#record-status').textContent='Grabando… Tu micrófono está activo.';
 }catch(e){recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;toast(e.name==='NotAllowedError'?'No se ha permitido el micrófono. Puedes habilitarlo en los permisos del navegador.':e.message||'No se pudo iniciar la grabación.');}
}
function stopAudio(){pronunciation.stop();const audio=$('#book-audio');audio?.pause();$('#voice-playback')?.pause();if(recorder?.state==='recording')recorder.stop();recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;if(audioURL){URL.revokeObjectURL(audioURL);audioURL=null;}loopStart=null;loopEnd=null;loopEnabled=false;}

function exportProgress(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`un-poco-de-chino-progreso-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Copia de progreso exportada. Los audios no se incluyen.');}
async function importProgress(file){if(!file)return;try{if(file.size>1024*1024)throw Error('El archivo de progreso es demasiado grande.');const incoming=validState(JSON.parse(await file.text()));if(Object.keys(state.records).length&&!confirm('Importar sustituirá tu progreso actual. ¿Quieres continuar?'))return;state=incoming;session=null;save();render();toast('Progreso importado.');}catch(e){toast(e.message||'No se pudo importar el archivo.');}}

function render(){nav();const html=route==='hoy'?today():route==='sesiones'?sessionsPage():route==='sesion'?unit():route==='practicar'?practice():route==='tarjetas'?studyTools.html():route==='sonidos'?pronunciation.html():route==='audios'?audioHTML():route==='semana'?weekHTML():progressHTML();$('#main').innerHTML=(storageWarning?'<div class="inline-notice">No se ha podido leer o guardar el progreso anterior. Puedes seguir practicando y exportar una copia desde Progreso.</div>':'')+html;if(route==='audios')wireAudio();}
function go(){let next=location.hash.slice(1).split('?')[0]||'hoy';if(route==='audios'||route==='sonidos')stopAudio();pronunciation.stop();const lesson=next.match(/^sesion-([123])$/);if(lesson){selectedLesson=+lesson[1];next='sesion';search='';category='todos';}if(next==='unidad'){selectedLesson=2;next='sesion';}route=['hoy','sesiones','sesion','practicar','tarjetas','sonidos','audios','progreso','semana'].includes(next)?next:'hoy';render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});}

document.addEventListener('click',e=>{
 const target=e.target.closest('button,a');if(!target)return;
 if(target.dataset.cardStart!==undefined){route='tarjetas';location.hash='tarjetas';}
 if(target.id==='sound-my-tone')stopAudio();
 if(pronunciation.onClick(target)||studyTools.onClick(target))return;
 if(target.dataset.train){practiceScope=target.dataset.scope||'';route='practicar';location.hash='practicar';startSession(target.dataset.train);}
 if(target.dataset.tab){lessonTab=target.dataset.tab;render();$(`[data-tab="${lessonTab}"]`)?.focus();}
 if(target.dataset.option!==undefined&&session&&!session.feedback){selected=session.items[session.index].options[+target.dataset.option];render();$(`[data-option="${target.dataset.option}"]`)?.focus();}
 if(target.dataset.token!==undefined&&!session.feedback){ordered.push(+target.dataset.token);render();}
 if(target.dataset.remove!==undefined&&!session.feedback){ordered=ordered.filter(i=>i!==+target.dataset.remove);render();}
 if(target.dataset.insert){const input=$('#answer'),start=input.selectionStart,end=input.selectionEnd;input.value=input.value.slice(0,start)+target.dataset.insert+input.value.slice(end);selected=input.value;$('#check-answer').disabled=!selected;input.focus();input.setSelectionRange(start+1,start+1);}
 if(target.dataset.track){stopAudio();activeTrack=target.dataset.track;render();}
 switch(target.id){
 case 'help-button':$('#info-dialog').showModal();break;
 case 'close-info':$('#info-dialog').close();break;
 case 'start-session':startSession();break;
 case 'new-session':startSession(session.mode);break;
 case 'start-recognition':startSession('recognition');break;
 case 'start-phrases':startSession('recognition-phrases');break;
 case 'start-errors':startSession('errors');break;
 case 'progress-errors':location.hash='practicar';route='practicar';startSession('errors');break;
 case 'check-answer':if(!session.feedback)checkAnswer();break;
 case 'next-question':nextQuestion();break;
 case 'exit-session':if(session.answers.length&&!confirm('¿Terminar este repaso? Las respuestas ya realizadas se conservan.'))break;session=null;render();break;
 case 'export-progress':exportProgress();break;
 case 'import-progress':$('#progress-file').click();break;
 case 'import-audio':$('#audio-files').click();break;
 case 'record-voice':toggleRecord();break;
 case 'mark-a':loopStart=$('#book-audio').currentTime;loopEnabled=false;if(loopEnd!==null&&loopEnd<=loopStart)loopEnd=null;loopStatus();break;
 case 'mark-b':if(loopStart===null){toast('Marca primero el inicio A.');break;}if($('#book-audio').currentTime<=loopStart+.2){toast('El final B debe estar después de A.');break;}loopEnd=$('#book-audio').currentTime;loopStatus();break;
 case 'toggle-loop':loopEnabled=!loopEnabled;if(loopEnabled){$('#book-audio').currentTime=loopStart;$('#book-audio').play().catch(()=>toast('Pulsa reproducir para escuchar el fragmento.'));}loopStatus();break;
 case 'clear-loop':loopStart=null;loopEnd=null;loopEnabled=false;loopStatus();break;
 }
 if(target.classList.contains('dialog-close'))$('#info-dialog').close();
});
document.addEventListener('input',e=>{if(pronunciation.onInput(e.target)||studyTools.onInput(e.target))return;if(e.target.id==='vocab-search'){search=e.target.value;$('#vocab-results').innerHTML=vocabCards();}if(e.target.id==='answer'){selected=e.target.value;$('#check-answer').disabled=!selected.trim();}});
document.addEventListener('change',e=>{const t=e.target;if(pronunciation.onChange(t)||studyTools.onChange(t))return;
 if(t.id==='show-pinyin'||t.id==='practice-pinyin'){if(t.id==='practice-pinyin'&&session?.items[session.index]?.kind==='recognition')recognitionHelp=t.checked;else{state.settings.pinyin=t.checked;save();}render();}
 if(t.id==='practice-scope'){practiceScope=t.value;}
 if(t.id==='extra-vocab'||t.id==='practice-extra'){state.settings.extra=t.checked;save();render();}
 if(t.id==='category'){category=t.value;$('#vocab-results').innerHTML=vocabCards();}
 if(t.id==='audio-unit'){stopAudio();audioUnit=t.value;activeTrack=null;render();}
 if(t.id==='audio-files')importAudio([...t.files]);
 if(t.id==='progress-file')importProgress(t.files[0]);
 if(t.dataset.task){state.checklist[t.dataset.task]=t.checked;save();t.closest('label').classList.toggle('done',t.checked);}
});
document.addEventListener('keydown',e=>{if(studyTools.onKeydown(e,route))return;if(e.key==='Enter'&&e.target.id==='answer'&&!e.isComposing&&!$('#check-answer')?.disabled){e.preventDefault();checkAnswer();}});
window.addEventListener('hashchange',go);
window.addEventListener('pagehide',()=>{save();stopAudio();});
go();readTracks();
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
